# filename: scripts/diag_features.py
"""Is the feature updater working? 1) invoke the Lambda directly, 2) read the smoke card's DynamoDB row."""
import base64, json, os, time, uuid
from datetime import datetime, timezone

from common.aws import client, resource

CARDS_FILE = os.environ.get("CARDS_FILE", "/data/cards.jsonl")


def invoke_directly():
    """One valid record for a dummy card. Any error here is a handler/runtime problem, not the trigger."""
    rec = {"event_id": f"diag-{uuid.uuid4()}", "card_token": "tok_diag_only", "decision": "APPROVE",
           "event_time": datetime.now(timezone.utc).isoformat(), "amount_minor": 1000,
           "merchant": {"country": "US"}}
    event = {"Records": [{"kinesis": {"data": base64.b64encode(json.dumps(rec).encode()).decode(),
                                      "sequenceNumber": "diag"}}]}
    r = client("lambda").invoke(FunctionName="feature-updater", Payload=json.dumps(event).encode(),
                                LogType="Tail")
    print("direct invoke:", r.get("FunctionError") or "OK", r["Payload"].read().decode()[:600])
    if r.get("LogResult"):                                  # last 4 KB of the Lambda's own log output
        print("lambda log tail:\n" + base64.b64decode(r["LogResult"]).decode(errors="replace")[-1500:])


def smoke_card_row():
    with open(CARDS_FILE) as fh:
        token = json.loads(fh.read().splitlines()[-1])["token"]    # smoke.py uses the last card
    item = resource("dynamodb").Table("card_features").get_item(
        Key={"card_token": token}, ConsistentRead=True).get("Item", {})
    age = time.time() - float(item.get("updated_at", 0))
    print(f"smoke card: recent={len(json.loads(item.get('recent', '[]')))} "
          f"txn_count_5m={item.get('txn_count_5m')} updated {age:.0f}s ago")


if __name__ == "__main__":
    invoke_directly()
    smoke_card_row()
